def listening_to_lessons(apps, schema_editor):
    """Each listening package becomes a lesson holding its worksheet and recordings.
    Quizzes and their attempts are not kept; the exercise instructions go in the notes."""
    Lesson = apps.get_model("library", "Lesson")
    LessonFile = apps.get_model("library", "LessonFile")
    for old in apps.get_model("library", "ListeningLesson").objects.order_by("id"):
        exercises = list(old.exercises.order_by("position"))
        notes = "\n\n".join([old.description] + [f"{e.position}. {e.title}\n{e.instructions}" for e in exercises]).strip()
        lesson = Lesson.objects.create(title=old.title[:200], notes=notes)
        files = [(old.pdf.name, "Worksheet.pdf")] + [
            (e.audio.name, f"{e.position}. {e.title}{PurePosixPath(e.audio.name).suffix}") for e in exercises]
        for i, (path, name) in enumerate(f for f in files if f[0]):
            LessonFile.objects.create(lesson=lesson, file=path, name=name[:200], position=i)


